mapper.select:
select * from (select a.id,a.policy_code policyCode,a.proj_id projId,b.proj_name projName,b.client_id clientId, a.insurance_start_date insuranceStartDate,a.insurance_end_date insuranceEndDate, a.insurance_company insuranceCompany,b.proj_sponsor_user_id projSponsorUserId, b.proj_cosponsor_user_ids projCosponsorUserIds,a.approval_status approvalStatus, a.renew_insurance_flag renewInsuranceFlag, a.contract_code contractCode, a.policy_status policyStatus, 'policy' as dataSource,a.create_time createTime,a.update_time updateTime, b.biz_dept_id biz_dept_id, a.identification_information identification_information,a.level renewalRelationship from policy_info a,proj_review_base_info b
a.proj_id = b.id and a.approval_status = #{req.approvalStatus}
AND a.id IN
#{item}
and a.data_status = #{req.dataStatus}
union all select a.id,a.policy_code policyCode,b.id projId,b.proj_name projName,b.client_id clientId, a.insurance_start_date insuranceStartDate,a.insurance_end_date insuranceEndDate, a.insurance_company insuranceCompany,b.proj_sponsor_user_id projSponsorUserId, b.proj_cosponsor_user_ids projCosponsorUserIds,d.payment_process_status approvalStatus, a.renew_insurance_flag renewInsuranceFlag, d.contract_code contractCode, "NEW_ADD" as policyStatus, 'payment' as dataSource,a.create_time createTime,d.update_time updateTime, b.biz_dept_id biz_dept_id, a.identification_information identification_information,'' renewalRelationship from payment_policy_info a,payment_base_info d,contract_base_info c,proj_review_base_info b
a.payment_id = d.id and d.contract_id = c.id and c.proj_review_id = b.id and d.payment_status = 'NEW' and d.payment_process_status = #{req.paymentApprovalStatus}
AND a.id IN
#{item}
union all select a.id,a.policy_code policyCode,b.id projId,b.proj_name projName,b.client_id clientId, a.insurance_start_date insuranceStartDate,a.insurance_end_date insuranceEndDate, a.insurance_company insuranceCompany,b.proj_sponsor_user_id projSponsorUserId, b.proj_cosponsor_user_ids projCosponsorUserIds,"UN_SUBMIT" approvalStatus, a.renew_insurance_flag renewInsuranceFlag, c.contract_code contractCode, "NEW_ADD" as policyStatus, 'payment' as dataSource,a.create_time createTime,a.update_time updateTime, b.biz_dept_id biz_dept_id, a.identification_information identification_information,'' renewalRelationship from payment_policy_info a,contract_base_info c,proj_review_base_info b
a.contract_id = c.id and c.proj_review_id = b.id and a.contract_id is not null and a.payment_id is null and 1=0
AND a.id IN
#{item}
) tmp
and tmp.clientId = #{req.clientId} and tmp.insuranceCompany LIKE concat('%', #{req.insuranceCompany},'%') and tmp.projName LIKE concat('%', #{req.projName},'%') and tmp.contractCode LIKE concat('%', #{req.contractCode},'%') and tmp.policyCode LIKE concat('%', #{req.policyCode},'%') and tmp.insuranceStartDate >= #{req.insuranceStartDateFrom} and tmp.insuranceStartDate <= #{req.insuranceStartDateTo} and tmp.insuranceEndDate >= #{req.insuranceEndDateFrom} and tmp.insuranceEndDate <= #{req.insuranceEndDateTo} and tmp.projSponsorUserId = #{req.projSponsorUserId}
and json_contains(tmp.projCosponsorUserIds, CONVERT(#{req.projCosponsorUserId},CHAR))
and tmp.dataSource != 'payment'
and tmp.dataSource != 'policy'
and tmp.renewInsuranceFlag = #{req.renewInsuranceFlag} and tmp.policyStatus = #{req.policyStatus}
and (tmp.projSponsorUserId = #{req.authId} OR JSON_CONTAINS(tmp.projCosponsorUserIds, CONVERT (#{req.authId}, CHAR)) )
and biz_dept_id in
#{item}
order by tmp.createTime desc

select a.policy_code, sum(a.policy_num) policy_num from (SELECT policy_code, count( 1 ) policy_num FROM payment_policy_info p INNER JOIN payment_base_info b ON p.payment_id = b.id WHERE b.payment_status != 'CLOSED' and p.policy_code in
#{item}
group by policy_code union all SELECT policy_code, count( 1 ) policy_num FROM policy_info where policy_code in
#{item}
group by policy_code) a group by a.policy_code
